param([string][Parameter(Mandatory=$true)]$rgName,[string][Parameter(Mandatory=$true)]$vmName)
$ErrorActionPreference='Stop'
# Ensure subscription context for UAMI in DeploymentScript container
$_ctx = Get-AzContext; if (-not $_ctx.Subscription.Id) { $_sub = (Get-AzSubscription -ErrorAction Stop | Select-Object -First 1).Id; Set-AzContext -SubscriptionId $_sub -ErrorAction Stop | Out-Null; Write-Output ("[INFO] Set subscription context to $_sub") }

Write-Output '[STEP 1] Checking initial BitLocker status for ALL volumes...'

# Build guest script that returns JSON with Drive and Pct for all mounted volumes
$guestScript = @'
function Get-EncryptionStatusJson {
    $ErrorActionPreference = "Stop"
    if (Get-Command Get-BitLockerVolume -ErrorAction SilentlyContinue) {
        $vols = Get-BitLockerVolume |
            Where-Object { $_.MountPoint } |
            Select-Object @{n='Drive';e={$_.MountPoint}}, @{n='Pct';e={[double]$_.EncryptionPercentage}}
        if ($vols) { return ($vols | ConvertTo-Json -Compress) }
    }
    $letters = (Get-Volume | Where-Object { $_.DriveLetter } | ForEach-Object { $_.DriveLetter + ':' })
    $list = @()
    foreach ($letter in $letters) {
        $out = & manage-bde -status $letter 2>&1
        $pctLine = ($out | Select-String -Pattern 'Percentage Encrypted:\s*(\d+(?:\.\d+)?)%')
        $pct = if ($pctLine -and $pctLine.Matches.Count -gt 0) { [double]$pctLine.Matches[0].Groups[1].Value } else { 0.0 }
        $list += [pscustomobject]@{ Drive = $letter; Pct = $pct }
    }
    if ($list.Count -gt 0) { return ($list | ConvertTo-Json -Compress) } else { return '[]' }
}
# Emit JSON to StdOut so RunCommand captures it
Get-EncryptionStatusJson
'@

# Initial sample
$init = Invoke-AzVMRunCommand -ResourceGroupName $rgName -Name $vmName -CommandId 'RunPowerShellScript' -ScriptString $guestScript
$initStdOut = ($init.Value | Where-Object { $_.Code -like '*StdOut*' }).Message
$initStdErr = ($init.Value | Where-Object { $_.Code -like '*StdErr*' }).Message
if ($initStdErr) { Write-Output ("[INFO] Initial StdErr: " + $initStdErr) }
try { $initVols = $initStdOut | ConvertFrom-Json } catch { $initVols = @() }
Write-Output ('[INFO] Initial volumes: ' + ( ($initVols | ForEach-Object { "{0}:{1}%" -f $_.Drive, $_.Pct }) -join ', ' ))

Write-Output '[STEP 2] Disabling Azure Disk Encryption for ALL volumes...'
Disable-AzVMDiskEncryption -ResourceGroupName $rgName -VMName $vmName -VolumeType All -Force
Write-Output '[INFO] Disable-AzVMDiskEncryption invoked.'

Write-Output '[STEP 3] Waiting until every BitLocker volume shows 0.0% (fully decrypted)...'
$iteration = 0
$allZero   = $false
$maxIters  = 480   # up to ~8 hours (60s intervals)

while (-not $allZero) {
    $iteration++
    Start-Sleep -Seconds 60

    # Ensure VM is running before polling guest
    $pwr = (Get-AzVM -ResourceGroupName $rgName -Name $vmName -Status).Statuses | Where-Object { $_.Code -like 'PowerState/*' } | Select-Object -First 1
    if (-not $pwr -or $pwr.Code -ne 'PowerState/running') {
        Write-Output ("[CHECK $iteration] VM power state is not running ({0}); waiting..." -f ($pwr.Code))
        if ($iteration -ge $maxIters) { throw "Timeout: VM not running after $maxIters iterations." }
        continue
    }

    # Poll guest for all drives' encryption %
    $poll = Invoke-AzVMRunCommand -ResourceGroupName $rgName -Name $vmName -CommandId 'RunPowerShellScript' -ScriptString $guestScript
    $msgOut = ($poll.Value | Where-Object { $_.Code -like '*StdOut*' }).Message
    $msgErr = ($poll.Value | Where-Object { $_.Code -like '*StdErr*' }).Message
    if ($msgErr) { Write-Output ("[CHECK $iteration] StdErr: " + $msgErr) }

    try { $vols = $msgOut | ConvertFrom-Json } catch { $vols = @() }
 if (-not $vols -or $vols.Count -eq 0) {
        Write-Output "[CHECK] No volumes found this iteration; retrying..."
        if ($iteration -ge $maxIters) { throw "Timeout: No volumes detected after $maxIters iterations." }
        continue
    }

    $statusLine = ( ($vols | ForEach-Object { "{0}:{1}%" -f $_.Drive, $_.Pct }) -join ', ' )
    Write-Output ("[CHECK $iteration] " + $statusLine)

    $allZero = ($vols | Where-Object { [double]$_.Pct -gt 0 }).Count -eq 0
    if (-not $allZero -and $iteration -ge $maxIters) { throw "Timeout: Not all volumes reached 0.0% after $maxIters iterations." }
}

Write-Output '[STEP 4] All volumes report 0.0% encryption. Removing ADE extension...'
Remove-AzVMExtension -ResourceGroupName $rgName -VMName $vmName -Name 'AzureDiskEncryption' -Force
Write-Output '[DONE] ADE extension removed successfully.'

param([string][Parameter(Mandatory=$true)]$rgName,[string][Parameter(Mandatory=$true)]$vmName)
$ErrorActionPreference='Stop'
# Ensure subscription context for UAMI in DeploymentScript container
$_ctx = Get-AzContext; if (-not $_ctx.Subscription.Id) { $_sub = (Get-AzSubscription -ErrorAction Stop | Select-Object -First 1).Id; Set-AzContext -SubscriptionId $_sub -ErrorAction Stop | Out-Null; Write-Output ("[INFO] Set subscription context to $_sub") }

# Get VM details
$vm = Get-AzVM -ResourceGroupName $rgName -Name $vmName -ErrorAction Stop

# Boot diagnostics capture
$bootEnabled = $false
$bootStorageUri = ''
if ($vm.DiagnosticsProfile -and $vm.DiagnosticsProfile.BootDiagnostics) {
    $bootEnabled = [bool]$vm.DiagnosticsProfile.BootDiagnostics.Enabled
    if ($vm.DiagnosticsProfile.BootDiagnostics.StorageUri) {
        $bootStorageUri = [string]$vm.DiagnosticsProfile.BootDiagnostics.StorageUri
    }
}

# Zones, Availability Set, Tags, Identity
$zone = ''
if ($vm.Zones -and $vm.Zones.Count -gt 0) { $zone = [string]$vm.Zones[0] }
$avSetId = ''
if ($vm.AvailabilitySet) { $avSetId = [string]$vm.AvailabilitySet.Id }
$tagsJson = ''
if ($vm.Tags) { $tagsJson = ($vm.Tags | ConvertTo-Json -Compress) }
$identityJson = ''
if ($vm.Identity) {
    $identityObj = [ordered]@{ type = $vm.Identity.Type; userAssigned = @() }
    if ($vm.Identity.UserAssignedIdentities) { $identityObj.userAssigned = $vm.Identity.UserAssignedIdentities.Keys }
    $identityJson = ($identityObj | ConvertTo-Json -Compress)
}

# Capture installed extensions
$extsJson = ''
try {
    $exts = Get-AzVMExtension -ResourceGroupName $rgName -VMName $vmName -ErrorAction SilentlyContinue
    if ($exts) {
        $payload = $exts | Select-Object Name,Publisher,ExtensionType,TypeHandlerVersion,AutoUpgradeMinorVersion,Settings
        $extsJson = ($payload | ConvertTo-Json -Compress -Depth 10)
    }
} catch {}

# Encode extensions JSON as Base64
$extsB64 = ''
if ($extsJson -and $extsJson.Trim().Length -gt 0) {
    try {
        $extsB64 = [System.Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($extsJson))
    } catch {
        $extsB64 = ''
    }
}

# Capture SecurityType
$securityType = ''
if ($vm.SecurityProfile -and $vm.SecurityProfile.SecurityType) {
    $securityType = [string]$vm.SecurityProfile.SecurityType
}

# Outputs
$DeploymentScriptOutputs = @{}
$DeploymentScriptOutputs['bootEnabled']       = $bootEnabled.ToString()
$DeploymentScriptOutputs['bootStorageUri']    = [string]$bootStorageUri
$DeploymentScriptOutputs['zone']              = [string]$zone
$DeploymentScriptOutputs['availabilitySetId'] = [string]$avSetId
$DeploymentScriptOutputs['vmSize']            = [string]$vm.HardwareProfile.VmSize
$DeploymentScriptOutputs['tagsJson']          = [string]$tagsJson
$DeploymentScriptOutputs['identityJson']      = [string]$identityJson
$DeploymentScriptOutputs['extensionsJsonB64'] = [string]$extsB64
$DeploymentScriptOutputs['securityType']      = [string]$securityType

param([string][Parameter(Mandatory=$true)]$rgName,[string][Parameter(Mandatory=$true)]$vmName,[string][Parameter(Mandatory=$true)]$timeStamp)
$ErrorActionPreference='Stop'
# Ensure subscription context for UAMI in DeploymentScript container
$_ctx = Get-AzContext; if (-not $_ctx.Subscription.Id) { $_sub = (Get-AzSubscription -ErrorAction Stop | Select-Object -First 1).Id; Set-AzContext -SubscriptionId $_sub -ErrorAction Stop | Out-Null; Write-Output ("[INFO] Set subscription context to $_sub") }
$ProgressPreference='SilentlyContinue'
$WarningPreference='SilentlyContinue'

Write-Output '[STEP 1] Loading source VM and inventorying disks...'
$vm = Get-AzVM -ResourceGroupName $rgName -Name $vmName -ErrorAction Stop
$targetRG = $rgName
$targetLocate = $vm.Location
Write-Output ("[INFO] VM Location: {0}" -f $targetLocate)

# Determine source SecurityType
$sourceSecurityType = ''
if ($vm.SecurityProfile -and $vm.SecurityProfile.SecurityType) { $sourceSecurityType = [string]$vm.SecurityProfile.SecurityType }
$hasSecurityType = ($sourceSecurityType -and $sourceSecurityType.Trim().Length -gt 0)
Write-Output ("[INFO] Source VM SecurityType: {0}" -f ( $hasSecurityType ? $sourceSecurityType : 'none/standard' ))

# OS Disk copy
$sourceOSDiskName = $vm.StorageProfile.OsDisk.Name
Write-Output ("[INFO] Source OS Disk: {0}" -f $sourceOSDiskName)
$sourceOSDisk = Get-AzDisk -ResourceGroupName $rgName -DiskName $sourceOSDiskName -ErrorAction Stop
$targetOSDiskName = "$sourceOSDiskName-$timeStamp"
Write-Output ("[INFO] Target OS Disk Name: {0}" -f $targetOSDiskName)

$targetOS = 'Windows'
$targetVmGeneration = $sourceOSDisk.HyperVGeneration
if ((-not $targetVmGeneration) -or ($targetVmGeneration.Trim().Length -eq 0)) { $targetVmGeneration = $vm.HyperVGeneration }
Write-Output ("[INFO] Hyper-V Generation: {0}" -f $targetVmGeneration)

$uploadOSSize = $sourceOSDisk.DiskSizeBytes + 512
$osSkuName = $sourceOSDisk.Sku.Name
if (-not $osSkuName -or ($osSkuName.Trim().Length -eq 0)) { $osSkuName = 'Standard_LRS' }
Write-Output ("[INFO] Source OS Disk SKU: {0}" -f $osSkuName)

$osDiskZone = $sourceOSDisk.Zones
if (-not $osDiskZone -and $vm.Zones) { $osDiskZone = $vm.Zones }
if ($osDiskZone -and ($osDiskZone -is [string])) { $osDiskZone = @($osDiskZone) }

if ($osDiskZone -and ($osDiskZone.Count -gt 0)) {
  $targetOSDiskConfig = New-AzDiskConfig -SkuName $osSkuName -OsType $targetOS -UploadSizeInBytes $uploadOSSize -Location $targetLocate -CreateOption 'Upload' -HyperVGeneration $targetVmGeneration -Zone $osDiskZone
} else {
  $targetOSDiskConfig = New-AzDiskConfig -SkuName $osSkuName -OsType $targetOS -UploadSizeInBytes $uploadOSSize -Location $targetLocate -CreateOption 'Upload' -HyperVGeneration $targetVmGeneration
}

# Apply Disk Security Profile ONLY if SecurityType is present
if ($hasSecurityType) {
  $targetOSDiskConfig = Set-AzDiskSecurityProfile -Disk $targetOSDiskConfig -SecurityType $sourceSecurityType
} else {
  Write-Output '[INFO] Source VM is Standard (no SecurityType). Skipping Set-AzDiskSecurityProfile for OS disk.'
}

$null = New-AzDisk -ResourceGroupName $targetRG -DiskName $targetOSDiskName -Disk $targetOSDiskConfig

# SAS and AzCopy
$sourceOSDiskSas = Grant-AzDiskAccess -ResourceGroupName $rgName -DiskName $sourceOSDiskName -DurationInSecond 86400 -Access 'Read'
$targetOSDiskSas = Grant-AzDiskAccess -ResourceGroupName $targetRG -DiskName $targetOSDiskName -DurationInSecond 86400 -Access 'Write'

Write-Output '[INFO] Downloading AzCopy for Linux (once)...'
$azCopyUrl = 'https://aka.ms/downloadazcopy-v10-linux'
$azCopyTar = 'azcopy.tar.gz'
if (-not (Test-Path $azCopyTar)) { Invoke-WebRequest -Uri $azCopyUrl -OutFile $azCopyTar -ErrorAction Stop }
try { if (-not (Get-ChildItem -Recurse | Where-Object { $_.Name -eq 'azcopy' })) { tar -xzf $azCopyTar } } catch { Write-Warning ("[WARN] tar extraction failed: {0}" -f $_.Exception.Message) }
$azCopyExe = (Get-ChildItem -Recurse | Where-Object { $_.Name -eq 'azcopy' } | Select-Object -First 1)
if (-not $azCopyExe) { throw '[ERROR] AzCopy executable not found after extraction.' }
Write-Output ("[INFO] AzCopy path: {0}" -f $azCopyExe.FullName)

& $azCopyExe.FullName copy $sourceOSDiskSas.AccessSAS $targetOSDiskSas.AccessSAS --blob-type PageBlob
Revoke-AzDiskAccess -ResourceGroupName $rgName -DiskName $sourceOSDiskName
Revoke-AzDiskAccess -ResourceGroupName $targetRG -DiskName $targetOSDiskName

$createdOSDisk = Get-AzDisk -ResourceGroupName $targetRG -DiskName $targetOSDiskName -ErrorAction Stop
Write-Output ("[INFO] Target OS disk security type: {0}" -f ( $createdOSDisk.SecurityType ? $createdOSDisk.SecurityType : 'none' ))
Write-Output '[STEP 1 DONE] OS disk copied successfully.'

# Data disks
Write-Output '[STEP 2] Copying all data disks (if any)...'
$dataDisks = $vm.StorageProfile.DataDisks
$copiedList = @()
if ($dataDisks -and $dataDisks.Count -gt 0) {
  foreach ($d in $dataDisks) {
    $srcDataName = $d.Name
    $srcDataLun  = $d.Lun
    $srcCaching  = [string]$d.Caching
    $srcDataDisk = Get-AzDisk -ResourceGroupName $rgName -DiskName $srcDataName -ErrorAction Stop
    $tgtDataName = "$srcDataName-$timeStamp"

    $dataSkuName = $srcDataDisk.Sku.Name
    if (-not $dataSkuName -or ($dataSkuName.Trim().Length -eq 0)) { $dataSkuName = 'Standard_LRS' }

    $dataZone = $srcDataDisk.Zones
    if (-not $dataZone -and $vm.Zones) { $dataZone = $vm.Zones }
    if ($dataZone -and ($dataZone -is [string])) { $dataZone = @($dataZone) }

    $uploadDataSize = $srcDataDisk.DiskSizeBytes + 512

    if ($dataZone -and ($dataZone.Count -gt 0)) {
      $tgtDataConfig = New-AzDiskConfig -SkuName $dataSkuName -UploadSizeInBytes $uploadDataSize -Location $targetLocate -CreateOption 'Upload' -Zone $dataZone
    } else {
      $tgtDataConfig = New-AzDiskConfig -SkuName $dataSkuName -UploadSizeInBytes $uploadDataSize -Location $targetLocate -CreateOption 'Upload'
    }

    # Apply Disk Security Profile ONLY if SecurityType is present
    if ($hasSecurityType) {
      $tgtDataConfig = Set-AzDiskSecurityProfile -Disk $tgtDataConfig -SecurityType $sourceSecurityType
    } else {
      Write-Output ("[INFO] Source VM is Standard (no SecurityType). Skipping Set-AzDiskSecurityProfile for data disk: {0}" -f $srcDataName)
    }

    $null = New-AzDisk -ResourceGroupName $targetRG -DiskName $tgtDataName -Disk $tgtDataConfig

    $srcDataSas = Grant-AzDiskAccess -ResourceGroupName $rgName -DiskName $srcDataName -DurationInSecond 86400 -Access 'Read'
    $tgtDataSas = Grant-AzDiskAccess -ResourceGroupName $targetRG -DiskName $tgtDataName -DurationInSecond 86400 -Access 'Write'

    & $azCopyExe.FullName copy $srcDataSas.AccessSAS $tgtDataSas.AccessSAS --blob-type PageBlob

    Revoke-AzDiskAccess -ResourceGroupName $rgName -DiskName $srcDataName
    Revoke-AzDiskAccess -ResourceGroupName $targetRG -DiskName $tgtDataName

    $createdData = Get-AzDisk -ResourceGroupName $targetRG -DiskName $tgtDataName -ErrorAction Stop
    Write-Output ("[INFO] Target data disk security type: {0}" -f ( $createdData.SecurityType ? $createdData.SecurityType : 'none' ))

    $copiedList += [PSCustomObject]@{ Source=$srcDataName; Target=$tgtDataName; Lun=$srcDataLun; Caching=$srcCaching }
  }
} else {
  Write-Output '[INFO] No data disks attached to the source VM.'
}

$DeploymentScriptOutputs = @{}
$DeploymentScriptOutputs['dataDisksCopiedJson'] = ($copiedList | ConvertTo-Json -Compress)
$DeploymentScriptOutputs['targetOSDiskName']    = [string]$targetOSDiskName
Write-Output '[STEP 2 DONE] All data disks processed.'

param([string][Parameter(Mandatory=$true)]$rgName,[string][Parameter(Mandatory=$true)]$vmName,[string][Parameter(Mandatory=$true)]$timeStamp,[string]$extensionsJsonB64,[string]$bootEnabled,[string]$bootStorageUri,[string]$securityType)
$ErrorActionPreference='Stop'
# Ensure subscription context for UAMI in DeploymentScript container
$_ctx = Get-AzContext; if (-not $_ctx.Subscription.Id) { $_sub = (Get-AzSubscription -ErrorAction Stop | Select-Object -First 1).Id; Set-AzContext -SubscriptionId $_sub -ErrorAction Stop | Out-Null; Write-Output ("[INFO] Set subscription context to $_sub") }
$ProgressPreference='SilentlyContinue'
$WarningPreference='SilentlyContinue'

# Normalize placeholders
if ($extensionsJsonB64 -eq '_NULL_') { $extensionsJsonB64 = '' }
if ($bootStorageUri    -eq '_NULL_') { $bootStorageUri    = '' }
if ($securityType      -eq '_NULL_') { $securityType      = '' }
$bootEnabledTrue = ($bootEnabled -match '^(?i:true)$')

# Ensure Az.Compute cmdlets available
Import-Module Az.Compute -ErrorAction SilentlyContinue

Write-Output '[STEP 3] Recreating VM from copied disks...'

# Decode extensions JSON from Base64
$extensionsJson = ''
if ($extensionsJsonB64 -and $extensionsJsonB64.Trim().Length -gt 0) {
    try { $extensionsJson = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($extensionsJsonB64)) } catch { Write-Warning ("[EXT] Failed to decode Base64: {0}" -f $_.Exception.Message) }
}

# Load source VM
$srcVm = Get-AzVM -ResourceGroupName $rgName -Name $vmName -ErrorAction Stop

# Compute target OS disk name
$sourceDiskName = $srcVm.StorageProfile.OsDisk.Name
$osDiskName = "$sourceDiskName-$timeStamp"
Write-Output ("[INFO] Target OS Disk to attach: {0}" -f $osDiskName)
$osDisk = Get-AzDisk -ResourceGroupName $rgName -DiskName $osDiskName -ErrorAction Stop
if ($osDisk.DiskState -eq 'Attached') { throw "Disk '$osDiskName' is attached" }

# NIC discovery
$nicIds = @()
if ($srcVm.NetworkProfile -and $srcVm.NetworkProfile.NetworkInterfaces) { $nicIds = $srcVm.NetworkProfile.NetworkInterfaces | ForEach-Object { $_.Id } }
if ((-not $nicIds) -or ($nicIds.Count -eq 0)) { $nicIds = (Get-AzNetworkInterface -ResourceGroupName $rgName | Where-Object { $_.VirtualMachine -and $_.VirtualMachine.Id -eq $srcVm.Id }) | ForEach-Object { $_.Id } }
if ((-not $nicIds) -or ($nicIds.Count -eq 0)) { throw "No NICs discovered for VM '$vmName'" }
$nicName = ((( $nicIds | Select-Object -First 1 )) -split '/')[-1]
$nic = Get-AzNetworkInterface -ResourceGroupName $rgName -Name $nicName -ErrorAction Stop

# Stop & delete source VM
Stop-AzVM -ResourceGroupName $rgName -Name $vmName -Force -ErrorAction SilentlyContinue | Out-Null
Remove-AzVM -ResourceGroupName $rgName -Name $vmName -Force | Out-Null
if ($nic.VirtualMachine) { $nic.VirtualMachine = $null; Set-AzNetworkInterface -NetworkInterface $nic | Out-Null }

# Build base VM config (source size)
$vmCfg = New-AzVMConfig -VMName $vmName -VMSize $srcVm.HardwareProfile.VmSize

# Preserve OS disk caching and attach OS disk
$osCaching = $srcVm.StorageProfile.OsDisk.Caching
Write-Output ("[INFO] Original OS disk caching: {0}" -f $osCaching)
$vmCfg = Set-AzVMOSDisk -VM $vmCfg -ManagedDiskId $osDisk.Id -CreateOption Attach -Windows -Caching $osCaching

# Attach NIC
$vmCfg = Add-AzVMNetworkInterface -VM $vmCfg -Id $nic.Id

# Apply SecurityType & UEFI; guard Gen2 for TL/CVM
if ($securityType -and $securityType.Trim().Length -gt 0) {
    if (-not $vmCfg.SecurityProfile) { $vmCfg.SecurityProfile = New-Object Microsoft.Azure.Management.Compute.Models.SecurityProfile }
    $vmCfg.SecurityProfile.SecurityType = $securityType
    if ($vmCfg.SecurityProfile.SecurityType -in @('TrustedLaunch','ConfidentialVM')) {
        if (-not $vmCfg.SecurityProfile.UefiSettings) { $vmCfg.SecurityProfile.UefiSettings = New-Object Microsoft.Azure.Management.Compute.Models.UefiSettings }
        $vmCfg.SecurityProfile.UefiSettings.VTpmEnabled = $true
        $vmCfg.SecurityProfile.UefiSettings.SecureBootEnabled = $true
        $diskGen = $osDisk.HyperVGeneration
        if ($diskGen -ne 'V2') { throw "SecurityType '$($vmCfg.SecurityProfile.SecurityType)' requires Gen2 (V2) OS disk. Current disk HyperVGeneration: '$diskGen'." }
    }
}

# Preserve Availability Set (if any)
if ($srcVm.AvailabilitySet) {
  $vmCfg.AvailabilitySet = New-Object Microsoft.Azure.Management.Compute.Models.SubResource
  $vmCfg.AvailabilitySet.Id = $srcVm.AvailabilitySet.Id
}

# --- Reapply Boot Diagnostics (Az 8.x compatible) ---
if ($bootEnabledTrue) {
    if (-not $vmCfg.DiagnosticsProfile) {
        $vmCfg.DiagnosticsProfile = New-Object Microsoft.Azure.Management.Compute.Models.DiagnosticsProfile
    }
    if (-not $vmCfg.DiagnosticsProfile.BootDiagnostics) {
        $vmCfg.DiagnosticsProfile.BootDiagnostics = New-Object Microsoft.Azure.Management.Compute.Models.BootDiagnostics
    }
    $vmCfg.DiagnosticsProfile.BootDiagnostics.Enabled = $true
    if ($bootStorageUri -and $bootStorageUri.Trim().Length -gt 0) {
        $vmCfg.DiagnosticsProfile.BootDiagnostics.StorageUri = $bootStorageUri
        Write-Output ("[INFO] Boot Diagnostics enabled with Storage URI: {0}" -f $bootStorageUri)
    } else {
        Write-Output "[INFO] Boot Diagnostics enabled without custom Storage URI"
    }
} else {
    Write-Output "[INFO] Boot Diagnostics was disabled on source VM; skipping."
}

# Re-attach all data disks with original LUN & caching
$dataDisks = $srcVm.StorageProfile.DataDisks
$attachCount = 0
if ($dataDisks -and $dataDisks.Count -gt 0) {
  foreach ($d in $dataDisks) {
    $srcDataName = $d.Name
    $tgtDataName = "$srcDataName-$timeStamp"
    $tgtData = Get-AzDisk -ResourceGroupName $rgName -DiskName $tgtDataName -ErrorAction Stop
    $lun = $d.Lun
    $caching = $d.Caching
    Write-Output ("[ATTACH] Data Disk: Name={0} -> {1}, LUN={2}, Caching={3}" -f $srcDataName, $tgtDataName, $lun, $caching)
    $vmCfg = Add-AzVMDataDisk -VM $vmCfg -Name $tgtDataName -ManagedDiskId $tgtData.Id -Lun $lun -Caching $caching -CreateOption Attach
    $attachCount++
  }
} else {
  Write-Output '[INFO] No data disks to attach.'
}

# Prepare create params (preserve zones & tags)
$createParams = @{ ResourceGroupName = $rgName; Location = $srcVm.Location; VM = $vmCfg }
if ($srcVm.Zones -and $srcVm.Zones.Count -gt 0) { $createParams['Zone'] = $srcVm.Zones }
if ($srcVm.Tags) { $createParams['Tag'] = $srcVm.Tags }

# Create VM
New-AzVM @createParams | Out-Null

# Apply extensions after VM creation
try {
    if ($extensionsJson -and $extensionsJson.Trim().Length -gt 0 -and $extensionsJson -ne '[]') {
        $extList = $extensionsJson | ConvertFrom-Json
        $skipNames = @('AzureDiskEncryption')
        foreach ($ext in $extList) {
            if ($skipNames -contains $ext.Name) { Write-Output ("[EXT] Skipping '{0}'" -f $ext.Name); continue }
            Write-Output ("[EXT] Applying {0} ({1}/{2} v{3})" -f $ext.Name, $ext.Publisher, $ext.ExtensionType, $ext.TypeHandlerVersion)
            $settingsJson = $null
            if ($ext.Settings) { $settingsJson = ($ext.Settings | ConvertTo-Json -Compress -Depth 10) }
            if ($settingsJson) {
                Set-AzVMExtension -ResourceGroupName $rgName -VMName $vmName -Name $ext.Name -Publisher $ext.Publisher -ExtensionType $ext.ExtensionType -TypeHandlerVersion $ext.TypeHandlerVersion -SettingString $settingsJson -ErrorAction Stop
            } else {
                Set-AzVMExtension -ResourceGroupName $rgName -VMName $vmName -Name $ext.Name -Publisher $ext.Publisher -ExtensionType $ext.ExtensionType -TypeHandlerVersion $ext.TypeHandlerVersion -ErrorAction Stop
            }
            Write-Output ("[EXT] Applied {0}" -f $ext.Name)
        }
    } else { Write-Output "[EXT] No extensionsJson provided or empty; skipping reapply." }
} catch { Write-Warning ("[EXT] Failed to set extensions: {0}" -f $_.Exception.Message) }

# Outputs
$DeploymentScriptOutputs = @{}
$DeploymentScriptOutputs['recreatedVmName'] = $vmName
$DeploymentScriptOutputs['attachedDataDiskCount'] = [int]$attachCount
Write-Output ('[DONE] VM recreated with OS + {0} data disk(s) attached.' -f $attachCount)

param([string][Parameter(Mandatory=$true)]$rgName,[string][Parameter(Mandatory=$true)]$vmName)
$ErrorActionPreference='Stop'
# Ensure subscription context for UAMI in DeploymentScript container
$_ctx = Get-AzContext; if (-not $_ctx.Subscription.Id) { $_sub = (Get-AzSubscription -ErrorAction Stop | Select-Object -First 1).Id; Set-AzContext -SubscriptionId $_sub -ErrorAction Stop | Out-Null; Write-Output ("[INFO] Set subscription context to $_sub") }
$ProgressPreference='SilentlyContinue'
$WarningPreference='SilentlyContinue'
try{$PSStyle.OutputRendering='PlainText'}catch{}
$vmStatus=Get-AzVM -ResourceGroupName $rgName -Name $vmName -Status -ErrorAction Stop
$prov=$vmStatus.Statuses|Where-Object{$_.Code -like 'ProvisioningState/*'}|Select-Object -First 1
$provCode=if($prov){$prov.Code}else{''}
if(-not $prov -or $prov.Code -ne 'ProvisioningState/succeeded'){throw ("VM '$vmName' provisioning state is not succeeded (actual: $provCode)")}
Stop-AzVM -ResourceGroupName $rgName -Name $vmName -Force|Out-Null
for($i=0;$i -lt 40;$i++){Start-Sleep -Seconds 6;$st=(Get-AzVM -ResourceGroupName $rgName -Name $vmName -Status).Statuses|Where-Object{$_.Code -like 'PowerState/*'}|Select-Object -First 1;if($st.Code -eq 'PowerState/deallocated'){break}}
if($st.Code -ne 'PowerState/deallocated'){throw ("VM '$vmName' did not reach PowerState/deallocated")}
$vmObj=Get-AzVM -ResourceGroupName $rgName -Name $vmName -ErrorAction Stop
if(-not $vmObj.SecurityProfile){$vmObj.SecurityProfile=New-Object Microsoft.Azure.Management.Compute.Models.SecurityProfile}
$vmObj.SecurityProfile.EncryptionAtHost=$true
Update-AzVM -ResourceGroupName $rgName -VM $vmObj|Out-Null
Start-AzVM -ResourceGroupName $rgName -Name $vmName|Out-Null
$final=Get-AzVM -ResourceGroupName $rgName -Name $vmName -Status
$eah=(Get-AzVM -ResourceGroupName $rgName -Name $vmName).SecurityProfile.EncryptionAtHost
$power=$final.Statuses|Where-Object{$_.Code -like 'PowerState/*'}|Select-Object -First 1
$DeploymentScriptOutputs=@{}
$DeploymentScriptOutputs['encryptionAtHostEnabled']=[bool]$eah
$DeploymentScriptOutputs['finalPowerState']=[string]$power.Code
